create table if not exists public.job_material_staging(id uuid primary key default gen_random_uuid(),purchase_order_id uuid references public.purchase_orders(id) on delete set null,customer_id uuid references public.customers(id) on delete set null,job_id uuid references public.jobs(id) on delete set null,inventory_item_id uuid references public.inventory_items(id) on delete set null,quantity numeric not null default 1 check(quantity>0),staging_location text,status text not null default 'staged' check(status in ('staged','loaded','delivered','used','returned')),label_code text unique,created_by uuid references public.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index if not exists job_material_staging_job_idx on public.job_material_staging(job_id,status);create index if not exists job_material_staging_customer_idx on public.job_material_staging(customer_id,status);alter table public.job_material_staging enable row level security;create policy "staff read material staging" on public.job_material_staging for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting','csr_dispatch','technician'));create policy "office manage material staging" on public.job_material_staging for all to authenticated using(private.current_employee_role() in ('owner','manager','accounting','csr_dispatch')) with check(private.current_employee_role() in ('owner','manager','accounting','csr_dispatch'));
create or replace function public.create_job_material_stage(p_purchase_order_id uuid,p_job_id uuid,p_inventory_item_id uuid,p_quantity numeric,p_staging_location text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_user public.users%rowtype;v_job public.jobs%rowtype;v_po public.purchase_orders%rowtype;v_id uuid;v_label text;begin select * into v_user from public.users where auth_user_id=auth.uid() and active=true limit 1;if v_user.id is null or v_user.role not in ('owner','manager','accounting','csr_dispatch') then raise exception 'not authorized';end if;if p_quantity<=0 then raise exception 'quantity must be positive';end if;select * into v_job from public.jobs where id=p_job_id;if v_job.id is null then raise exception 'job not found';end if;if p_purchase_order_id is not null then select * into v_po from public.purchase_orders where id=p_purchase_order_id;if v_po.id is null then raise exception 'PO not found';end if;if v_po.customer_id is not null and v_po.customer_id<>v_job.customer_id then raise exception 'PO customer does not match job customer';end if;end if;insert into public.job_material_staging(purchase_order_id,customer_id,job_id,inventory_item_id,quantity,staging_location,created_by) values(p_purchase_order_id,v_job.customer_id,p_job_id,p_inventory_item_id,p_quantity,nullif(trim(p_staging_location),''),v_user.id) returning id into v_id;v_label:='STG-'||upper(substr(replace(v_id::text,'-',''),1,10));update public.job_material_staging set label_code=v_label where id=v_id;return v_id;end$$;revoke all on function public.create_job_material_stage(uuid,uuid,uuid,numeric,text) from public,anon;grant execute on function public.create_job_material_stage(uuid,uuid,uuid,numeric,text) to authenticated;
